import mpmath as mp

def eml_value(a: mp.mpf) -> mp.mpf:
    if a <= -1:
        raise ValueError("a must exceed -1")
    return mp.exp(a) * mp.log1p(a)

def main() -> None:
    mp.mp.dps = 60
    values = [mp.mpf("-0.5"), mp.mpf("0"), mp.mpf("0.25"), mp.sqrt(2), mp.sqrt(3)]
    for a in values:
        value = eml_value(a)
        expected = -1 if a < 0 else (1 if a > 0 else 0)
        print(mp.nstr(a, 12), mp.nstr(value, 45), "expected sign", expected)

if __name__ == "__main__":
    main()

