from __future__ import annotations
from itertools import product
import mpmath as mp

def eml_value(a: mp.mpf) -> mp.mpf:
    return mp.exp(a) * mp.log1p(a)

def main(height: int = 12) -> None:
    mp.mp.dps = 80
    u, v = eml_value(mp.sqrt(2)), eml_value(mp.sqrt(3))
    best: tuple[mp.mpf, tuple[int, int, int]] | None = None
    for c in product(range(-height, height + 1), repeat=3):
        if c == (0, 0, 0) or next(x for x in reversed(c) if x) < 0:
            continue
        residual = abs(c[0] + c[1] * u + c[2] * v)
        if best is None or residual < best[0]:
            best = (residual, c)
    assert best is not None
    print("bounds: degree 1, height", height, "precision", mp.mp.dps)
    print("best coefficients", best[1])
    print("residual", mp.nstr(best[0], 40))
    print("Finite numerical screen only; no independence conclusion follows.")

if __name__ == "__main__":
    main()

