from __future__ import annotations
import mpmath as mp

def guarded_eml(a: str, digits: int, guard: int = 15) -> str:
    if digits < 1 or guard < 0:
        raise ValueError("invalid precision")
    with mp.workdps(digits + guard):
        x = mp.mpf(a)
        if x <= -1:
            raise ValueError("a must exceed -1")
        value = mp.exp(x) * mp.log1p(x)
        return mp.nstr(value, digits)

if __name__ == "__main__":
    print(guarded_eml("1.4142135623730950488", 50))

from __future__ import annotations
from itertools import product
from typing import Sequence
import mpmath as mp

def relation_screen(x: mp.mpf, y: mp.mpf, degree: int, height: int) -> tuple[tuple[int, ...], mp.mpf]:
    mons = tuple((i, t-i) for t in range(degree + 1) for i in range(t + 1))
    best: tuple[tuple[int, ...], mp.mpf] | None = None
    for c in product(range(-height, height + 1), repeat=len(mons)):
        if not any(c) or next(v for v in reversed(c) if v) < 0:
            continue
        r = abs(mp.fsum(v*x**i*y**j for v,(i,j) in zip(c, mons)))
        if best is None or r < best[1]:
            best = (tuple(c), r)
    if best is None:
        raise ValueError("empty search")
    return best

